const $=id=>document.getElementById(id), t=k=>window.PoseTokiI18n?.t(k)??k, locale=()=>({'ko':'ko-KR','ja':'ja-JP','en':'en-US','zh-TW':'zh-TW'}[window.PoseTokiI18n?.lang]||'ko-KR');
let mode='preset',seconds=60,preview=0,uploads=[],queue=[],index=0,remaining=3,preparing=true,paused=false,active=false,spent=0,last=0,interval=null,flip=false,zoomed=false,seen=new Set(),audio=null;
const poses=['서 있는 자세','앉은 자세','걷는 자세','한 팔 뻗기','옆으로 기울이기','균형 잡기','걷는 중','넓은 런지','뒤돌아보기','의자에 걸터앉기','바닥에 앉기','앞으로 기대기','한쪽 무릎 꿇기','낮은 스쿼트','옆으로 앉기','앞으로 숙이기','한 발로 서기','벽 밀기','내려서는 동작','편하게 서기','앉아서 비틀기'];
function setPose(el,i){el.style.backgroundImage=`url("assets/pose-${String(i+1).padStart(2,'0')}.jpg")`;el.style.backgroundSize='contain';el.style.backgroundPosition='center';el.style.backgroundRepeat='no-repeat'}function paintPreview(){setPose($('heroPhoto'),preview);const n=String(preview+1).padStart(2,'0'),p=t(poses[preview]);$('imageLabel').textContent=window.PoseTokiI18n?.lang==='ja'?`${n} / ${poses.length}・${p}`:window.PoseTokiI18n?.lang==='zh-TW'?`${n} / ${poses.length} · ${p}`:`${n} / ${poses.length} · ${p}`; }
$('nextPreview').onclick=()=>{preview=(preview+1)%poses.length;paintPreview()};$('prevPreview').onclick=()=>{preview=(preview+poses.length-1)%poses.length;paintPreview()};
function selectMode(m){mode=m;$('presetTab').classList.toggle('selected',m==='preset');$('ownTab').classList.toggle('selected',m==='own');$('presetContent').hidden=m!=='preset';$('ownContent').hidden=m!=='own';updateEstimate()}
$('presetTab').onclick=()=>selectMode('preset');$('ownTab').onclick=()=>selectMode('own');
function setTime(s){seconds=s;document.querySelectorAll('[data-time]').forEach(b=>b.classList.toggle('selected',Number(b.dataset.time)===s));updateEstimate()}
document.querySelectorAll('[data-time]').forEach(b=>b.onclick=()=>{ $('customField').hidden=true;$('customBtn').classList.remove('selected');setTime(Number(b.dataset.time))});
$('customBtn').onclick=()=>{$('customField').hidden=false;setTime(Number($('customSeconds').value));$('customBtn').classList.add('selected')};$('customSeconds').oninput=()=>setTime(Number($('customSeconds').value));$('count').onchange=updateEstimate;
function updateEstimate(){const n=Number($('count').value);$('estimate').textContent=window.PoseTokiI18n?.lang==='ko'?`${n}장 · 약 ${Math.round(n*seconds/60*10)/10}분`:window.PoseTokiI18n?.lang==='ja'?`${n}ポーズ・約${Math.round(n*seconds/60*10)/10}分`:window.PoseTokiI18n?.lang==='zh-TW'?`${n} 個姿勢 · 約 ${Math.round(n*seconds/60*10)/10} 分鐘`:`${n} ${t('poses')} · about ${Math.round(n*seconds/60*10)/10} ${t('min')}`}
async function addFiles(files){$('error').textContent='';let added=0;for(const file of files){if(!file.type.startsWith('image/'))continue;const url=URL.createObjectURL(file);const ok=await new Promise(resolve=>{const img=new Image();img.onload=()=>resolve(true);img.onerror=()=>resolve(false);img.src=url});if(ok){uploads.push({url,name:file.name});added++}else URL.revokeObjectURL(url)}$('fileStatus').textContent=window.PoseTokiI18n?.lang==='ko'?`${uploads.length}장 준비 완료 · 사진은 이 기기에서만 사용됩니다.`:window.PoseTokiI18n?.lang==='ja'?`${uploads.length}枚準備完了・写真はこの端末内だけで使用します`:window.PoseTokiI18n?.lang==='zh-TW'?`已準備 ${uploads.length} 張 · 照片只會留在此裝置`: `${uploads.length} photos ready · ${t('내 사진은 내 기기에만')}`;if(!added)$('error').textContent=t('읽을 수 있는 이미지 파일을 선택해주세요.')}
$('files').onchange=e=>addFiles(e.target.files);$('drop').ondragover=e=>{e.preventDefault();$('drop').classList.add('drag')};$('drop').ondragleave=()=>$('drop').classList.remove('drag');$('drop').ondrop=e=>{e.preventDefault();$('drop').classList.remove('drag');addFiles(e.dataTransfer.files)};
function tone(){if(!$('sound').checked)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();audio.resume();const o=audio.createOscillator(),g=audio.createGain();o.connect(g);g.connect(audio.destination);o.frequency.value=660;g.gain.setValueAtTime(.035,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.18);o.start();o.stop(audio.currentTime+.2)}catch{}}
function start(){if(!Number.isFinite(seconds)||seconds<5||seconds>3600){$('error').textContent=t('5초에서 3600초 사이의 시간을 입력해주세요.');return false}if(mode==='own'&&!uploads.length){$('error').textContent=t('먼저 연습할 사진을 선택해주세요.');return false}const pool=mode==='own'?uploads.map((p,i)=>({...p,key:i})):poses.map((name,i)=>({name,key:i}));queue=[];while(queue.length<Number($('count').value)){const batch=[...pool];if($('shuffle').checked){for(let j=batch.length-1;j>0;j--){const k=Math.floor(Math.random()*(j+1));[batch[j],batch[k]]=[batch[k],batch[j]]}}queue.push(...batch)}queue=queue.slice(0,Number($('count').value));index=0;spent=0;seen=new Set();preparing=true;remaining=3;paused=false;active=true;flip=false;zoomed=false;$('pause').textContent=t('일시정지');$('error').textContent='';if(!$('session').open)$('session').showModal();render();last=performance.now();clearInterval(interval);interval=setInterval(tick,100);try{audio??=new(window.AudioContext||window.webkitAudioContext)();audio.resume()}catch{}return true}
$('start').onclick=start;
function tick(){const now=performance.now();const delta=(now-last)/1000;last=now;if(!active||paused)return;remaining-=delta;if(!preparing)spent+=delta;if(remaining<=0){if(preparing){preparing=false;remaining=seconds;seen.add(index);tone()}else{move(1);return}}renderTimer()}
function renderTimer(){const s=Math.max(0,Math.ceil(remaining));$('timer').textContent=`${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`;$('phase').textContent=preparing?t('연필을 준비하세요'):paused?t('잠깐 쉬어가는 중'):t('몸의 흐름을 관찰해보세요');$('timerBar').style.width=`${Math.max(0,remaining/(preparing?3:seconds)*100)}%`}
function render(){const p=queue[index];$('progress').textContent=window.PoseTokiI18n?.lang==='ko'?`${index+1} / ${queue.length} 포즈`:`${index+1} / ${queue.length} ${t('poses')}`;$('sessionPhoto').hidden=mode==='own';$('localPhoto').hidden=mode!=='own';if(mode==='own'){$('localPhoto').src=p.url;$('localPhoto').alt=p.name}else setPose($('sessionPhoto'),p.key);$('sessionSource').textContent=t(mode==='own'?'내 사진 · 서버 전송 없이 이 기기에서만':'AI 생성 예시 · 21개 포즈 순환 · 관절과 비례를 확인하세요');$('sessionSound').textContent=t($('sound').checked?'♪ 전환음 켜짐':'♪ 전환음 꺼짐');transform();renderTimer()}
function move(d){if(!active)return;if(index+d>=queue.length){finishSession();return}index=Math.max(0,index+d);preparing=false;remaining=seconds;seen.add(index);last=performance.now();tone();render()}
function pause(){if(!active)return;paused=!paused;last=performance.now();$('pause').textContent=t(paused?'계속 그리기':'일시정지');renderTimer()}
$('pause').onclick=pause;$('next').onclick=()=>move(1);$('previous').onclick=()=>move(-1);function transform(){const t=`scale(${flip?-1:1},1) scale(${zoomed?1.4:1})`;$('sessionPhoto').style.transform=t;$('localPhoto').style.transform=t}$('mirror').onclick=()=>{flip=!flip;transform()};$('zoom').onclick=()=>{zoomed=!zoomed;$('zoom').textContent=t(zoomed?'− 축소':'＋ 확대');transform()};async function fullscreen(){try{if(document.fullscreenElement)await document.exitFullscreen();else await $('session').requestFullscreen()}catch{}}$('full').onclick=fullscreen;$('sessionSound').onclick=()=>{$('sound').checked=!$('sound').checked;render()};window.addEventListener('posetoki-language',()=>{updateEstimate();paintPreview();if(active){render();$('pause').textContent=t(paused?'계속 그리기':'일시정지')} });document.addEventListener('DOMContentLoaded',()=>{updateEstimate();paintPreview()});
function history(){try{return JSON.parse(localStorage.getItem('posetoki-history')||'[]')}catch{return []}}
function showInfo(title,content){$('infoContent').replaceChildren();const h=document.createElement('h2');h.textContent=title;$('infoContent').append(h,content);$('info').showModal()}
function finishSession(){if(!active)return;active=false;clearInterval(interval);if(document.fullscreenElement)document.exitFullscreen().catch(()=>{});$('session').close();const total=Math.round(spent);let saved=true;if(total>0){try{const h=history();h.unshift({date:new Date().toISOString(),seconds:total,count:seen.size});localStorage.setItem('posetoki-history',JSON.stringify(h.slice(0,100)))}catch{saved=false}}const div=document.createElement('div');const p=document.createElement('p');p.className='info-copy';p.textContent=window.PoseTokiI18n?.lang==='ja'?`${seen.size}ポーズを観察し、${Math.floor(total/60)}分${total%60}秒描きました。${saved?'練習記録をこの端末に保存しました。':'このブラウザでは練習記録を保存できませんでした。'} 下の写真を選ぶと拡大して復習できます。`:window.PoseTokiI18n?.lang==='zh-TW'?`觀察了 ${seen.size} 個姿勢，練習 ${Math.floor(total/60)} 分 ${total%60} 秒。${saved?'練習紀錄已儲存在此裝置。':'此瀏覽器無法儲存練習紀錄。'} 點選下方照片即可放大複習。`:window.PoseTokiI18n?.lang==='en'?`You observed ${seen.size} poses and drew for ${Math.floor(total/60)} min ${total%60} sec. ${saved?'Your practice was saved on this device.':'This browser could not save the practice log.'} Select a photo below to review it larger.`:`${seen.size}포즈를 관찰하고 ${Math.floor(total/60)}분 ${total%60}초 동안 그렸어요. ${saved?'기기에 연습 기록을 남겼어요.':'이 브라우저에서는 기록을 저장할 수 없어요.'} 아래 사진을 눌러 크게 복습하세요.`;div.append(p);const grid=document.createElement('div');grid.className='review-grid';const keys=new Set();[...seen].sort((a,b)=>a-b).forEach(i=>{const item=queue[i];if(keys.has(item.key))return;keys.add(item.key);const b=document.createElement('button');b.className='review-item';b.setAttribute('aria-label',window.PoseTokiI18n?.lang==='ja'?`${t(item.name)}を復習`:window.PoseTokiI18n?.lang==='en'?`Review ${t(item.name)}`:window.PoseTokiI18n?.lang==='zh-TW'?`複習${t(item.name)}`:`${item.name} 복습`);const image=mode==='own'?document.createElement('img'):document.createElement('div');if(mode==='own'){image.src=item.url;image.alt=item.name}else{image.className='pose-photo';setPose(image,item.key)}const label=document.createElement('small');label.textContent=t(item.name);b.append(image,label);b.onclick=()=>{const copy=image.cloneNode();copy.style.height='60vh';copy.style.width='100%';$('infoContent').replaceChildren(copy);const back=document.createElement('button');back.textContent=t('복습 목록으로');back.className='quiet';back.onclick=()=>{$('infoContent').replaceChildren();const h=document.createElement('h2');h.textContent=t('오늘도, 한 걸음 그렸어요.');$('infoContent').append(h,div)};$('infoContent').append(back)};grid.append(b)});div.append(grid);showInfo(t('오늘도, 한 걸음 그렸어요.'),div)}
$('finish').onclick=finishSession;$('session').addEventListener('cancel',e=>{e.preventDefault();finishSession()});$('closeInfo').onclick=()=>$('info').close();
$('recordBtn').onclick=()=>{const div=document.createElement('div');const records=history();const copy=document.createElement('p');copy.className='info-copy';copy.textContent=records.length?(window.PoseTokiI18n?.lang==='ja'?`合計${records.reduce((s,r)=>s+r.count,0)}ポーズ・${Math.round(records.reduce((s,r)=>s+r.seconds,0)/60)}分。記録はこのブラウザだけに保存され、ブラウザデータを消去すると削除されます。`:window.PoseTokiI18n?.lang==='zh-TW'?`累計 ${records.reduce((s,r)=>s+r.count,0)} 個姿勢 · ${Math.round(records.reduce((s,r)=>s+r.seconds,0)/60)} 分鐘。紀錄只存在此瀏覽器，清除瀏覽器資料後便會消失。`:window.PoseTokiI18n?.lang==='en'?`Total: ${records.reduce((s,r)=>s+r.count,0)} poses · ${Math.round(records.reduce((s,r)=>s+r.seconds,0)/60)} min. The log stays in this browser and is erased if browser data is cleared.`:`누적 ${records.reduce((s,r)=>s+r.count,0)}포즈 · ${Math.round(records.reduce((s,r)=>s+r.seconds,0)/60)}분. 기록은 이 브라우저에만 저장되며, 브라우저 데이터를 삭제하면 사라집니다.`):t('아직 연습 기록이 없어요. 첫 번째 선을 시작해볼까요? 기록은 이 브라우저에만 저장됩니다.');div.append(copy);records.slice(0,15).forEach(r=>{const p=document.createElement('div');p.className='history';p.textContent=window.PoseTokiI18n?.lang==='ja'?`${new Date(r.date).toLocaleString(locale())} · ${r.count}ポーズ · ${Math.floor(r.seconds/60)}分${r.seconds%60}秒`:window.PoseTokiI18n?.lang==='zh-TW'?`${new Date(r.date).toLocaleString(locale())} · ${r.count} 個姿勢 · ${Math.floor(r.seconds/60)} 分 ${r.seconds%60} 秒`:window.PoseTokiI18n?.lang==='en'?`${new Date(r.date).toLocaleString(locale())} · ${r.count} poses · ${Math.floor(r.seconds/60)} min ${r.seconds%60} sec`:`${new Date(r.date).toLocaleString(locale())} · ${r.count}포즈 · ${Math.floor(r.seconds/60)}분 ${r.seconds%60}초`;div.append(p)});showInfo(t('나의 작은 연습 기록'),div)};
document.querySelectorAll('[data-course]').forEach(b=>b.onclick=()=>{const deep=b.dataset.course==='deep';selectMode('preset');setTime(deep?180:b.dataset.course==='warm'?30:60);$('count').value=deep?'5':'10';$('customField').hidden=true;$('customBtn').classList.remove('selected');updateEstimate();$('practice').scrollIntoView({behavior:'smooth'});$('start').focus({preventScroll:true})});
document.addEventListener('keydown',e=>{if(!$('session').open||['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName))return;if(e.code==='Space'){e.preventDefault();pause()}if(e.key==='ArrowRight'){e.preventDefault();move(1)}if(e.key==='ArrowLeft'){e.preventDefault();move(-1)}if(e.key.toLowerCase()==='m')$('mirror').click();if(e.key.toLowerCase()==='f')fullscreen()});
window.addEventListener('beforeunload',()=>uploads.forEach(p=>URL.revokeObjectURL(p.url)));
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'configure_practice',description:'Set the prepared-pose practice duration and pose count, without starting the session.',inputSchema:{type:'object',properties:{seconds:{type:'integer',minimum:5,maximum:3600},count:{type:'integer',enum:[5,10,15,20]}},required:['seconds','count'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!Number.isInteger(input.seconds)||input.seconds<5||input.seconds>3600||![5,10,15,20].includes(input.count))throw new Error('Invalid practice settings');if(active)throw new Error('Finish the current session first');selectMode('preset');setTime(input.seconds);$('count').value=String(input.count);$('customField').hidden=[30,60,180,300].includes(input.seconds);$('customSeconds').value=input.seconds;updateEstimate();return{seconds,count:input.count,source:'generated sample poses'}}})).catch(()=>{})}catch{}}
